// https://github.com/amandaghassaei/gpu-io/blob/main/examples/fluid/index.js
var fluid;

// https://github.com/amandaghassaei/canvas-capture
var canvasCapture;
var capturedFrames = 0;

// Touch events.
const activeTouches = {};
const TOUCH_DIAMETER = 25;

//Vamoss
var points = [];//vamoss shape

function setup() {	
	//hack to enable p5js WEBGL2
	if(GPUIO.isWebGL2Supported()){
		p5.RendererGL.prototype._initContext = function() {
			try {
				this.drawingContext =
					this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
					this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
				if (this.drawingContext === null) {
					throw new Error('Error creating webgl2 context');
				} else {
					const gl = this.drawingContext;
					gl.enable(gl.DEPTH_TEST);
					gl.depthFunc(gl.LEQUAL);
					gl.viewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight);
					this._viewport = this.drawingContext.getParameter(
						this.drawingContext.VIEWPORT
					);
				}
			} catch (er) {
				throw er;
			}
		};
	}

	var renderer = createCanvas(windowWidth, windowHeight, WEBGL);

	canvasCapture = window.CanvasCapture.CanvasCapture;
	const RECORD_FPS = 60;

	// Init a simple gui.
	const gui = new dat.GUI();

	fluid = new Fluid(renderer.canvas, gui);
	fluid.resize(width, height);

	canvasCapture.dispose();
	canvasCapture.init(renderer.canvas, { showRecDot: true, showDialogs: true, showAlerts: true, recDotCSS: { left: '0', right: 'auto' } });
	canvasCapture.bindKeyToVideoRecord('v', {
		format: CanvasCapture.WEBM,
		name: 'screen_recording',
		fps: RECORD_FPS,
		quality: 1,
	});

	const radius = max(width, height) - 150;
	const x = width / 2 - radius / 2;
	const y = height / 2 - radius / 2;
	Vamoss(1, x, y, radius);

function draw() {
	copyVamossToVectorField();
	fluid.draw();

	// Screen recording.
	canvasCapture.checkHotkeys();
	if (canvasCapture.isRecording()) {
		canvasCapture.recordFrame();
		capturedFrames++;
		console.log(`Recording duration: ${(capturedFrames / RECORD_FPS).toFixed(2)} sec`);
	} else {
		capturedFrames = 0;
	}
}

function mouseMoved(e){
	const current = [e.clientX, e.clientY];
	if (activeTouches[e.pointerId] === undefined) {
		activeTouches[e.pointerId] = {
			current: current,
		}
		return;
	}
	var last = activeTouches[e.pointerId].last = activeTouches[e.pointerId].current;
	activeTouches[e.pointerId].current = current;

	if (current[0] == last[0] && current[1] == last[1]) {
		return;
	}

	fluid.pointerMove(current, last);
}

function mouseReleased(e){
	delete activeTouches[e.pointerId];
}

function keyPressed(){
	if(key == "p"){
		fluid.savePNG();
	}
}

function windowResized() {
  fluid.resize(windowWidth, windowHeight);
}

function Vamoss(pct, x, y, radius){
	pct = constrain(pct, 0.0001, 1);

	const scale = radius / 135;
	const circleRadius = 5;//small circles max size
	const space = 2.5;//space between the small circles

	//magic numbers
	const ampVel = 0.0017;
	const phase = 0.25;
	const freq = 1.54;

	var amp = 0;
	var r = 0;
	var simpleSin, simpleCos, complexSin, complexCos;

	var last1, last2;
	for(var t = 0; t < 7.92 * pct; t += (Math.max(0.001, Math.abs(0.01 * space)) || 1)){
		if(t < 5){
			if(r < circleRadius * scale)
				r += 0.01 * space * scale;
		}else{
			if(r > 0)
				r -= 0.017 * space * scale;
		}

		if(amp < 1)
			amp += ampVel * space;

		simpleSin = sin(t) * radius / 2 + radius / 2;
		complexCos = cos(t * freq + HALF_PI + phase) * amp * radius / 2 + radius / 2;

		var coord1 = [x + simpleSin, y + complexCos];
		var coord2 = [x + radius - simpleSin, y + complexCos];

		if(last1 && last2){
			points.push([coord1, last1]);
			points.push([coord2, last2]);
		}
		last1 = coord1;
		last2 = coord2;
	}
}

function copyVamossToVectorField(){
	//if(frameCount % 60 == 0){
		const res = 31;
		for(var i = frameCount%res; i < points.length; i+=(Math.max(0.001, Math.abs(res)) || 1)){
			fluid.pointerMove(points[i][0], points[i][1]);
		}
	//}
}
